INSERT INTO events (id, title, kind, description, location, start_at, end_at, capacity, fee, created_at, updated_at) VALUES
  ('18000000-0000-4000-8000-000000000001', 'Junior Coaching Camp', 'CAMP', 'Five mornings of drills, match play and fitness for players under 18, led by our head coaches. Happening now — a few seats left for the final sessions.', 'Badminton Courts 1–2 and Tennis Court 2', '2026-10-01T01:30:00.000Z', '2026-10-05T03:30:00.000Z', 24, '3500.00', '2026-03-17T04:30:00.000Z', '2026-03-17T04:30:00.000Z'),
  ('18000000-0000-4000-8000-000000000002', 'Padel Beginners Clinic', 'CLINIC', 'Learn the rules, walls and doubles tactics in a relaxed two-hour clinic. Rackets provided.', 'Padel Court 1', '2026-10-10T03:30:00.000Z', '2026-10-10T05:30:00.000Z', 12, '800.00', '2026-03-17T04:30:00.000Z', '2026-03-17T04:30:00.000Z'),
  ('18000000-0000-4000-8000-000000000003', 'Autumn Open — Tennis Tournament', 'TOURNAMENT', 'Our flagship weekend tournament: singles and doubles draws, seeded brackets, live scoring and a finals-night dinner at the café.', 'Tennis Courts 1 & 2 · finals on Court 1', '2026-10-17T02:30:00.000Z', '2026-10-18T13:30:00.000Z', 32, '1500.00', '2026-03-17T04:30:00.000Z', '2026-03-17T04:30:00.000Z'),
  ('18000000-0000-4000-8000-000000000004', 'Members’ Mixer & Live Music', 'MIXER', 'An evening on the café terrace: live acoustic set, tasting plates and a chance to meet your playing partners.', 'Bar & Café terrace', '2026-10-24T13:30:00.000Z', '2026-10-24T16:30:00.000Z', 80, '0.00', '2026-03-17T04:30:00.000Z', '2026-03-17T04:30:00.000Z');
